insert into public.services
  (slug, position, published, icon, name, tagline, summary, hero_title, hero_lead, outcomes, signals, deliverables, process, stack, engagement, faqs, industries, case_studies, seo_title, seo_description)
values
  ('full-stack-development', 10, true, 'stack', 'Full Stack Development', 'Web platforms built end to end by one accountable team.', 'We design, build and run complete web platforms: interface, API, database and cloud infrastructure. One team owns the whole system, so nothing falls between vendors.', 'One team for the interface, the API, the database and the uptime.', 'Most failed software projects fail at the joins between teams. We put front end, back end, QA and DevOps in one squad with one delivery manager, and we ship working software every two weeks.', '[{"value":"2 weeks","label":"between every working release you can click through"},{"value":"99.9%","label":"uptime target written into our production support agreements"},{"value":"100%","label":"of source code, infrastructure and documentation owned by you"}]'::jsonb, array['Your product roadmap is blocked because front end and back end work sits with two different vendors.', 'A previous agency delivered code that nobody on your side can maintain or deploy.', 'Your platform slows down or fails at peak load and nobody can say exactly why.', 'You need a first release in the market within one quarter and cannot hire a full team that fast.', 'Reports are assembled by hand because your systems do not share a database or an API.']::text[], '[{"title":"Technical discovery and architecture","body":"A written architecture document, data model and delivery plan before any feature work starts. You approve it, then we build to it."},{"title":"Production web application","body":"A responsive interface in React and Next.js, tested on current Chrome, Safari, Edge and Firefox, on desktop and mobile."},{"title":"APIs and integrations","body":"Documented REST or GraphQL APIs, plus integrations with your payment provider, CRM, accounting system and identity provider."},{"title":"Cloud infrastructure as code","body":"AWS, Azure or Google Cloud environments defined in Terraform, with separate staging and production and automated deployments."},{"title":"Automated test suite","body":"Unit, integration and end to end tests that run on every pull request. A release does not ship if the suite fails."},{"title":"Handover and runbooks","body":"Architecture diagrams, deployment runbooks and a recorded walkthrough so your own engineers can take over at any time."}]'::jsonb, '[{"title":"Discover","body":"One to two weeks of workshops with your stakeholders. We map users, data and integrations, then return a fixed scope, timeline and price."},{"title":"Design","body":"Clickable prototypes for the core flows and a reviewed architecture. You see how the product works before we write production code."},{"title":"Build","body":"Two week sprints. Every sprint ends with a demo on a staging environment that you can use yourself."},{"title":"Launch and support","body":"A rehearsed production release, 30 days of warranty support, and an optional monthly retainer with agreed response times."}]'::jsonb, array['TypeScript', 'React', 'Next.js', 'Node.js', 'NestJS', 'Python', 'Django', '.NET', 'PostgreSQL', 'Redis', 'AWS', 'Docker']::text[], '{"timeline":"First production release in 10 to 16 weeks","team":"4 to 7 people: tech lead, 2 to 4 engineers, QA, delivery manager","model":"Fixed scope for a defined release, or a dedicated monthly team"}'::jsonb, '[{"q":"What drives the cost of a full stack project?","a":"Three things: the number of distinct user roles and screens, the number of third party integrations, and compliance requirements such as SOC 2 or PCI DSS. After discovery we give you a fixed price for a defined scope, with each cost driver itemised so you can remove or defer items."},{"q":"Who owns the code?","a":"You do. The contract assigns all intellectual property to you on payment of each invoice. The code lives in your GitHub or GitLab organisation from the first commit, and the cloud accounts are in your name."},{"q":"Can you take over a codebase another team started?","a":"Yes. We start with a paid two week audit covering code quality, security, test coverage and infrastructure. You get a written report that says what to keep, what to repair and what to replace, with estimates for each."},{"q":"How will we communicate during the project?","a":"Your delivery manager is in Canada and works Eastern hours. Stand ups, demos and reviews are scheduled in your working day, and you have a shared channel with the engineers for questions in between."},{"q":"What happens after launch?","a":"Every project includes 30 days of warranty support at no charge. After that, most clients move to a monthly retainer that covers monitoring, security patches and a fixed number of development hours."}]'::jsonb, array['fintech', 'logistics', 'real-estate', 'education']::text[], array['logistics-driver-app', 'hospital-management-system', 'retail-storefront-rebuild']::text[], 'Full Stack Development Services', 'Full stack web development by the senior engineers of a Canadian software company. React, Next.js, Node.js, .NET and cloud infrastructure, delivered in two week releases with full code ownership.'),
  ('frontend-development', 20, true, 'browser', 'Front End Development', 'Fast, accessible interfaces in React and Next.js.', 'We build the part of your product that customers see and judge. Interfaces that load in under two seconds, pass accessibility audits and stay consistent as your team adds features.', 'Your customers judge the whole company by the first two seconds.', 'A slow or confusing interface costs you sign ups and sales every day it stays live. We rebuild front ends in React and Next.js with measured performance budgets, WCAG 2.2 AA accessibility and a component library your team can keep extending.', '[{"value":"< 2.0s","label":"Largest Contentful Paint target on a mid range phone over 4G"},{"value":"WCAG 2.2 AA","label":"accessibility standard we test every release against"},{"value":"90+","label":"Lighthouse performance score before we call a page done"}]'::jsonb, array['Your pages fail Core Web Vitals and organic traffic has dropped as a result.', 'The same button looks five different ways because there is no shared component library.', 'A legacy Angular.js, jQuery or server rendered front end makes every new feature slow to ship.', 'An accessibility complaint or a procurement questionnaire has asked for WCAG conformance.', 'Your back end team is strong but nobody owns the interface.']::text[], '[{"title":"Performance and UX audit","body":"A measured baseline of Core Web Vitals, bundle size and conversion drop off, with a ranked list of fixes."},{"title":"Design system and component library","body":"Typed React components documented in Storybook, with design tokens that match your Figma files."},{"title":"Production front end","body":"Next.js or React application with server rendering, image optimisation and code splitting configured correctly."},{"title":"Accessibility conformance","body":"Keyboard, screen reader and contrast testing against WCAG 2.2 AA, with a conformance report you can give to procurement teams."},{"title":"Analytics and SEO foundations","body":"Structured data, metadata, sitemaps and event tracking wired in from the first release."},{"title":"Visual regression tests","body":"Automated screenshot comparison on every pull request, so a change in one screen cannot quietly break another."}]'::jsonb, '[{"title":"Audit","body":"We measure what users experience today: load times, error rates and where they abandon. You get the numbers in the first week."},{"title":"System","body":"We agree on tokens, typography and core components with your designers, then build the library before the pages."},{"title":"Migrate","body":"Screens move to the new front end one route at a time. The old and new versions run side by side, so there is no big bang release."},{"title":"Measure","body":"We compare Core Web Vitals and conversion against the baseline and keep tuning until the targets are met."}]'::jsonb, array['TypeScript', 'React', 'Next.js', 'Tailwind CSS', 'Storybook', 'Playwright', 'Vitest', 'GraphQL', 'TanStack Query', 'Figma', 'Vercel']::text[], '{"timeline":"Audit in 1 week, first migrated routes live in 4 to 6 weeks","team":"3 to 5 people: front end lead, 1 to 3 engineers, QA","model":"Fixed scope rebuild, or engineers embedded in your product team"}'::jsonb, '[{"q":"Can you work with our existing back end and designers?","a":"Yes. Most front end engagements run against an API your team already owns. We work from your Figma files, join your stand ups and open pull requests in your repository."},{"q":"Do we have to rewrite everything at once?","a":"No. We migrate route by route behind a reverse proxy, so the legacy and new front ends serve traffic together. You see value from the first migrated page and can pause at any point."},{"q":"How do you prove the new front end is faster?","a":"We record Core Web Vitals from real users before work starts and after each release. The comparison is in a dashboard you can open yourself. If a page misses its target, it goes back into the sprint."},{"q":"What does a front end rebuild cost?","a":"Cost depends on the number of unique screens, how much of a design system already exists and how clean the API is. After a one week audit you get a fixed price per phase."}]'::jsonb, array['retail-ecommerce', 'fintech', 'real-estate', 'education']::text[], array['retail-storefront-rebuild']::text[], 'Front End Development Services in React and Next.js', 'Front end development in React and Next.js. Design systems, Core Web Vitals performance and WCAG 2.2 AA accessibility, built by senior engineers and migrated route by route.'),
  ('erp-development', 30, true, 'erp', 'ERP System Development', 'One system for finance, inventory, HR and operations.', 'We build and customise ERP systems that match how your company operates, then migrate your data without stopping the business. Finance, inventory, purchasing, HR and reporting in one place.', 'Stop running a multi million dollar company on spreadsheets and re-keyed data.', 'When finance, inventory and operations live in separate tools, every month end is a reconciliation exercise. We build an ERP around your actual processes, migrate your history and train your staff, with a go live plan your auditors can sign off.', '[{"value":"5 days","label":"typical month end close after go live, down from 12 to 15"},{"value":"Zero","label":"unplanned downtime during cutover with a parallel run"},{"value":"1 ledger","label":"shared by finance, inventory, purchasing and sales"}]'::jsonb, array['Month end close takes more than ten working days because data is reconciled by hand.', 'Stock counts in the warehouse do not match what the accounting system says.', 'You pay per user licence fees for an off the shelf ERP and still export to Excel to get answers.', 'Staff enter the same order into three systems.', 'Your current ERP vendor has ended support or cannot build the workflow you need.']::text[], '[{"title":"Process map and gap analysis","body":"Every current workflow documented, with a clear decision on what the ERP will handle as standard and what needs custom work."},{"title":"Core modules","body":"General ledger, accounts payable and receivable, inventory, purchasing, sales orders, HR and payroll, configured to your chart of accounts."},{"title":"Custom workflows","body":"Approval chains, pricing rules, production planning or anything else specific to how you operate, built as maintainable modules."},{"title":"Data migration","body":"Customers, suppliers, open orders, stock and historical ledgers cleaned, mapped and reconciled to the cent before cutover."},{"title":"Reporting and dashboards","body":"Live financial statements, stock ageing, margin by product and any report your board asks for, without an export."},{"title":"Training and go live support","body":"Role based training sessions, written guides and engineers on call through your first two month end closes."}]'::jsonb, '[{"title":"Map","body":"Three to four weeks with your department heads. We document every process and agree what changes and what stays."},{"title":"Configure and build","body":"Standard modules first, then custom workflows. You test each module with real data as it is completed."},{"title":"Migrate and parallel run","body":"Old and new systems run together for one full accounting period. Balances must match before we cut over."},{"title":"Go live and stabilise","body":"Cutover on a weekend, engineers on site or on call the following week, then 60 days of stabilisation support."}]'::jsonb, array['Odoo', 'ERPNext', 'Microsoft Dynamics 365', 'Python', '.NET', 'PostgreSQL', 'SQL Server', 'Power BI', 'REST APIs', 'EDI', 'Azure']::text[], '{"timeline":"First modules live in 4 to 6 months, full rollout in 6 to 12","team":"5 to 9 people: ERP architect, functional consultants, engineers, QA, trainer","model":"Phased fixed price per module, followed by a support retainer"}'::jsonb, '[{"q":"Should we build a custom ERP or customise an existing platform?","a":"In most cases we recommend an open platform such as Odoo or ERPNext with custom modules for the 20 percent of processes that make your business different. A fully custom ERP makes sense only when your operations do not fit any standard model. We give you a costed comparison during discovery."},{"q":"How do you migrate data without stopping the business?","a":"We run three trial migrations before the real one. Each is reconciled against your existing system, and discrepancies are fixed at the source. The final cutover happens over a weekend after a full parallel run."},{"q":"What does an ERP project cost?","a":"The main drivers are the number of modules, the number of legal entities and locations, the volume and quality of legacy data, and the number of integrations. We price each module separately so you can phase the investment."},{"q":"Will our staff actually use it?","a":"Adoption is planned from the first week. Department leads test each module during the build, training is role based, and we stay on call for the first two month end closes. Screens are designed around the tasks people do every day."},{"q":"Can it connect to our bank, payroll provider and e-commerce store?","a":"Yes. We integrate bank feeds, payroll services, Shopify and other storefronts, shipping carriers and EDI trading partners through documented APIs."}]'::jsonb, array['manufacturing', 'logistics', 'retail-ecommerce', 'healthcare']::text[], array['distributor-erp-migration']::text[], 'Custom ERP System Development and Migration', 'ERP development and migration for finance, inventory, purchasing and HR. Odoo, ERPNext and Dynamics 365 customisation with reconciled data migration and parallel run go live.'),
  ('ai-chatbots', 40, true, 'chat', 'AI Chatbots', 'Assistants that answer from your data and know when to hand over.', 'We build AI assistants for customer support, sales and internal teams. They answer from your own documents and systems, cite their sources and pass the conversation to a person when they should.', 'An assistant that answers from your data, cites it, and knows when to stop.', 'A chatbot that guesses is a liability. Ours retrieve answers from your approved knowledge base, show the source, complete tasks through your APIs and escalate to your staff with the full conversation attached.', '[{"value":"40-60%","label":"of routine enquiries resolved without a human agent"},{"value":"< 5 sec","label":"median response time, at any hour"},{"value":"100%","label":"of answers traceable to a source document"}]'::jsonb, array['Your support team answers the same 30 questions hundreds of times a month.', 'Customers wait hours for a reply outside business hours.', 'New staff take weeks to find answers buried in policy documents and wikis.', 'You tried an off the shelf bot and it gave wrong or invented answers.', 'Leads arrive on your website and WhatsApp at night and nobody qualifies them until morning.']::text[], '[{"title":"Knowledge pipeline","body":"Your documents, help centre and product data indexed for retrieval, with an update process so the assistant never answers from stale content."},{"title":"Assistant with guardrails","body":"Retrieval augmented generation with source citations, topic limits and refusal rules agreed with your compliance team."},{"title":"Task integrations","body":"Order status, appointment booking, account lookups and ticket creation through your existing APIs."},{"title":"Channels","body":"Website widget, WhatsApp Business, Slack or Microsoft Teams, and voice where it fits."},{"title":"Human handover","body":"Escalation to your agents in Zendesk, Intercom or HubSpot with the transcript and a summary attached."},{"title":"Evaluation and monitoring","body":"A test set of real questions scored on every change, plus a dashboard for resolution rate, escalations and flagged answers."}]'::jsonb, '[{"title":"Scope","body":"We analyse 3 to 6 months of your support tickets to find which questions the assistant should own and which stay with people."},{"title":"Pilot","body":"A working assistant on your real content in 3 to 4 weeks, tested by your own staff before any customer sees it."},{"title":"Harden","body":"We score accuracy against a test set, add guardrails, connect integrations and run a security review."},{"title":"Roll out","body":"Launch to a percentage of traffic, compare against the human baseline, then expand as the numbers hold."}]'::jsonb, array['Claude', 'OpenAI GPT', 'LangChain', 'LlamaIndex', 'pgvector', 'Pinecone', 'Python', 'FastAPI', 'WhatsApp Business API', 'Twilio', 'Zendesk', 'AWS Bedrock']::text[], '{"timeline":"Pilot in 3 to 4 weeks, production in 8 to 10","team":"3 to 5 people: AI lead, 1 to 2 engineers, QA, delivery manager","model":"Fixed price pilot, then fixed scope production build"}'::jsonb, '[{"q":"How do you stop the assistant from making things up?","a":"It answers only from retrieved content and shows the source. When retrieval finds nothing relevant, it says so and offers a handover. Every release is scored against a test set of real questions, and answers below the accuracy threshold block the release."},{"q":"Is our data used to train public models?","a":"No. We use enterprise API terms from Anthropic, OpenAI or AWS Bedrock, under which your data is not used for training. For stricter requirements we deploy models inside your own cloud account with Canadian data residency."},{"q":"What does it cost to run?","a":"There are two parts: the build, which is fixed price, and usage, which depends on conversation volume and model choice. We estimate monthly usage from your ticket history before you commit and set spending caps in production."},{"q":"Will it replace our support team?","a":"It takes the repetitive questions. Your team keeps the complex cases, complaints and anything that needs judgment, and receives them with context already gathered."},{"q":"Which model do you use?","a":"We test two or three models against your own questions during the pilot and choose on accuracy, latency and cost. The architecture keeps the model swappable, so you are not locked to one provider."}]'::jsonb, array['fintech', 'healthcare', 'retail-ecommerce', 'education']::text[], array['lender-ai-support-assistant']::text[], 'AI Chatbot Development for Support and Sales', 'Custom AI chatbots that answer from your own data with citations, complete tasks through your APIs and hand over to staff. Built on Claude and GPT with guardrails and evaluation.'),
  ('ai-automation', 50, true, 'automation', 'AI Automation', 'Remove the manual work between your systems.', 'We automate the repetitive work that sits between your systems: reading documents, entering data, routing requests and producing reports. Staff review exceptions instead of processing every item.', 'Your best people should not spend their day copying data between screens.', 'Invoices, claims, applications and orders still pass through someone''s hands because the systems do not talk. We build automations that read the document, apply your rules, update the system of record and send only the exceptions to a person.', '[{"value":"70-85%","label":"of documents processed without manual touch"},{"value":"Minutes","label":"to process items that used to wait days in a queue"},{"value":"Full audit trail","label":"of every automated decision and who approved exceptions"}]'::jsonb, array['Staff re-key data from PDFs, emails or scanned forms into another system.', 'A backlog builds every month end and you hire temporary staff to clear it.', 'Errors from manual entry cause refunds, rework or compliance findings.', 'Requests arrive by email and wait for someone to read and forward them.', 'You have automation scripts that break whenever a screen or a format changes.']::text[], '[{"title":"Process assessment","body":"Volumes, handling time and error rates measured for each candidate process, ranked by payback period."},{"title":"Document intelligence","body":"Extraction from invoices, IDs, claims and contracts using OCR and language models, with confidence scores on every field."},{"title":"Workflow orchestration","body":"Rules, approvals and retries defined in a workflow engine, so a failed step resumes instead of being lost."},{"title":"System integrations","body":"Direct API connections to your ERP, CRM, accounting and email. Screen automation only where no API exists."},{"title":"Exception queue","body":"A review screen where staff confirm or correct low confidence items. Corrections feed back to improve accuracy."},{"title":"Monitoring and audit log","body":"Dashboards for throughput and accuracy, and a record of each decision for auditors."}]'::jsonb, '[{"title":"Measure","body":"We shadow the process and pull the numbers: items per month, minutes per item, error rate. You see the business case before you spend on a build."},{"title":"Prove","body":"A proof of concept on 200 to 500 of your real documents in 2 to 3 weeks, with measured accuracy."},{"title":"Build","body":"Production workflow, integrations and exception handling, tested against edge cases your staff identify."},{"title":"Run and tune","body":"We monitor accuracy weekly for the first quarter and adjust rules and prompts as real volumes come through."}]'::jsonb, array['Python', 'Claude', 'OpenAI GPT', 'Azure AI Document Intelligence', 'AWS Textract', 'Temporal', 'n8n', 'Apache Airflow', 'PostgreSQL', 'Power Automate', 'REST APIs']::text[], '{"timeline":"Proof of concept in 2 to 3 weeks, first process live in 6 to 10","team":"3 to 5 people: automation architect, 1 to 2 engineers, QA, delivery manager","model":"Fixed price per process, with a retainer for monitoring and new workflows"}'::jsonb, '[{"q":"Which processes are worth automating?","a":"High volume, rule based work with digital inputs. If a process handles more than 500 items a month and each takes more than three minutes, it usually pays back within a year. The assessment gives you a payback figure for each candidate."},{"q":"What happens when the automation is not sure?","a":"Every extracted field carries a confidence score. Items below the threshold go to a review queue with the uncertain fields highlighted. Nothing is posted to your system of record on a guess."},{"q":"Do we need to replace our existing systems?","a":"No. Automation sits between the systems you already have. We connect through APIs where they exist and use controlled screen automation where they do not."},{"q":"How do you handle sensitive documents?","a":"Processing runs in your cloud account or in a Canadian region, data is encrypted in transit and at rest, and access is logged. We sign a data processing agreement and can work to PIPEDA, PHIPA and SOC 2 requirements."}]'::jsonb, array['fintech', 'logistics', 'healthcare', 'manufacturing']::text[], array['lender-ai-support-assistant']::text[], 'AI Automation and Intelligent Document Processing', 'AI automation for invoices, claims, applications and back office workflows. Document extraction, workflow orchestration and exception queues with a full audit trail.'),
  ('mobile-app-development', 60, true, 'mobile', 'Mobile App Development', 'Native and cross-platform apps for iOS and Android.', 'We build iOS and Android apps for customers and field teams, from first prototype to App Store release and beyond. Native where performance demands it, cross-platform where one codebase saves you money.', 'An app people keep on their home screen, on iOS and Android.', 'Users delete apps that crash, drain the battery or ask them to log in twice. We build mobile apps in Swift, Kotlin, React Native and Flutter that work offline, pass store review the first time and hold a crash free rate above 99.5 percent.', '[{"value":"99.5%+","label":"crash free sessions target for every production release"},{"value":"2 stores","label":"App Store and Google Play submission handled by us"},{"value":"12 weeks","label":"typical time from kickoff to a first public release"}]'::jsonb, array['Your customers use the mobile website and abandon tasks they would finish in an app.', 'Field staff fill in paper forms and type them up at the end of the day.', 'Your current app has a store rating below four stars and reviews mention crashes.', 'You maintain separate iOS and Android codebases and features ship months apart.', 'The app stops working when there is no signal.']::text[], '[{"title":"Product definition and prototype","body":"User flows and a clickable prototype tested with real users before development starts."},{"title":"iOS and Android apps","body":"Native Swift and Kotlin, or a shared React Native or Flutter codebase. We recommend the approach and explain the trade offs in writing."},{"title":"Back end and admin console","body":"APIs, authentication, push notifications and a web console for your staff to manage content and users."},{"title":"Offline mode and sync","body":"Local storage with conflict handling, so the app keeps working in basements, warehouses and rural routes."},{"title":"Store submission","body":"Listings, screenshots, privacy declarations and review responses for the App Store and Google Play."},{"title":"Release pipeline and analytics","body":"Automated builds, staged rollouts, crash reporting and product analytics from day one."}]'::jsonb, '[{"title":"Define","body":"Two weeks to agree on the core user tasks and cut everything that does not belong in version one."},{"title":"Prototype","body":"A clickable prototype on real devices. We test it with five to eight users and fix what confuses them."},{"title":"Build","body":"Two week sprints with a TestFlight and Play internal build at the end of each one."},{"title":"Release and iterate","body":"Staged rollout, monitoring of crashes and reviews, then a regular release cadence."}]'::jsonb, array['Swift', 'SwiftUI', 'Kotlin', 'Jetpack Compose', 'React Native', 'Flutter', 'Firebase', 'Node.js', 'GraphQL', 'SQLite', 'Fastlane']::text[], '{"timeline":"First store release in 12 to 16 weeks","team":"4 to 6 people: mobile lead, 2 mobile engineers, back end engineer, QA, designer","model":"Fixed scope for version one, then a monthly release retainer"}'::jsonb, '[{"q":"Native or cross-platform?","a":"Cross-platform with React Native or Flutter suits most business apps and saves 30 to 40 percent of build cost. We recommend native Swift and Kotlin when the app relies on heavy graphics, Bluetooth devices, or deep platform features. You get our recommendation and reasoning in the proposal."},{"q":"What does a mobile app cost?","a":"The drivers are the number of screens, whether a back end already exists, offline requirements, payment and third party integrations, and whether you need one platform or two. We fix the price for version one after a two week definition phase."},{"q":"Do you handle App Store and Google Play approval?","a":"Yes. We prepare listings, privacy declarations and review notes, submit under your developer accounts and respond to any review feedback. The accounts and the apps stay in your name."},{"q":"Can you rescue an app another team built?","a":"Yes. We begin with a code and crash audit, stabilise the current release, then agree a plan to repair or rebuild module by module."},{"q":"How are updates handled after launch?","a":"Each year Apple and Google release new OS versions that require updates. A release retainer covers OS compatibility, security patches, monitoring and a set number of feature hours each month."}]'::jsonb, array['logistics', 'healthcare', 'restaurants-hospitality', 'retail-ecommerce']::text[], array['logistics-driver-app']::text[], 'Mobile App Development for iOS and Android', 'iOS and Android app development in Swift, Kotlin, React Native and Flutter. Offline first apps, store submission and release management by senior mobile engineers.'),
  ('custom-pos-systems', 70, true, 'pos', 'Custom POS Systems', 'Point of sale that keeps selling when the internet drops.', 'We build point of sale systems for retailers and restaurants with needs that packaged POS cannot meet. Offline selling, multi-branch inventory, your pricing rules and your choice of payment processor.', 'A point of sale that fits your counter, your rules and your payment processor.', 'Packaged POS charges per terminal, locks you to its payment rates and goes dark when the connection drops. We build a POS you own: it sells offline, syncs every branch to one inventory and reports to head office in real time.', '[{"value":"100%","label":"of sales captured during internet outages, synced on reconnect"},{"value":"< 1 sec","label":"to add an item and move to the next, on standard hardware"},{"value":"$0","label":"per terminal licence fees. You own the software"}]'::jsonb, array['Per terminal and per transaction fees rise every time you open a location.', 'Tills freeze or lose sales when the internet is unstable.', 'Stock levels across branches are reconciled by hand at the end of the week.', 'Your pricing, promotions or loyalty rules do not fit the options in your current POS.', 'Head office waits until the next morning for yesterday''s sales figures.']::text[], '[{"title":"POS terminal application","body":"A touch interface for Windows, Android or iPad with barcode scanning, split payments, returns and shift management."},{"title":"Offline first architecture","body":"Each terminal holds a local database and continues selling without a connection. Transactions sync and reconcile when it returns."},{"title":"Payments integration","body":"Integration with Moneris, Stripe Terminal, Square, Global Payments or your regional processor, using certified devices so card data never touches the POS."},{"title":"Inventory and purchasing","body":"Stock by location, transfers, purchase orders and low stock alerts in one back office."},{"title":"Head office console","body":"Live sales by branch, product and cashier, with price and promotion changes pushed to every terminal."},{"title":"Hardware and rollout","body":"Tested receipt printers, cash drawers, scanners and customer displays, plus an installation and training plan for each site."}]'::jsonb, '[{"title":"Observe","body":"We spend time at your busiest counter to see how staff actually ring up sales, handle returns and close a shift."},{"title":"Pilot","body":"One location runs the new POS alongside the old one for two to four weeks."},{"title":"Refine","body":"Cashier feedback from the pilot is built in before any wider rollout."},{"title":"Roll out","body":"Branches go live in waves, with on site or remote support during each first week."}]'::jsonb, array['.NET', 'React', 'Electron', 'Kotlin', 'Flutter', 'SQLite', 'PostgreSQL', 'Stripe Terminal', 'Moneris', 'ESC/POS', 'Azure']::text[], '{"timeline":"Pilot store live in 12 to 16 weeks","team":"4 to 7 people: solution architect, 2 to 3 engineers, QA, rollout lead","model":"Fixed price build and pilot, then per wave rollout and support retainer"}'::jsonb, '[{"q":"Why build a POS instead of buying one?","a":"Buying is right for a single shop with standard needs. Building pays off when you run many terminals, have pricing or workflow rules a package cannot support, or want to choose your own payment processor. We will tell you plainly if a packaged product is the better choice."},{"q":"Is a custom POS PCI compliant?","a":"Yes. We use certified payment terminals with point to point encryption, so card numbers never pass through the POS software. That keeps your PCI DSS scope small. We document the architecture for your assessor."},{"q":"Can it work with our existing hardware?","a":"Usually. We test your printers, scanners, drawers and scales during discovery and list any device that needs replacing."},{"q":"How does offline mode handle stock and card payments?","a":"Sales and stock movements are stored locally and synced in order when the connection returns. Card payments depend on your processor: many terminals support store and forward for a limited amount, which we configure with your acquirer."},{"q":"Does it connect to our accounting system and online store?","a":"Yes. We integrate with QuickBooks, Xero, Sage, Shopify and WooCommerce so sales, tax and stock stay consistent."}]'::jsonb, array['restaurants-hospitality', 'retail-ecommerce']::text[], array['restaurant-group-pos-rollout']::text[], 'Custom POS System Development for Retail and Restaurants', 'Custom point of sale systems with offline selling, multi-branch inventory and integrated payments. PCI aware architecture, no per terminal licence fees, full ownership.'),
  ('management-software', 80, true, 'management', 'Hospital and Restaurant Software', 'Management systems shaped around how your floor runs.', 'We build hospital management systems and restaurant management systems for operators who have outgrown generic software. Scheduling, records, billing, kitchen and inventory in one system built around your daily routine.', 'Management software built around the way your wards and kitchens run.', 'Hospitals and restaurants share one problem: many people, many handoffs, no room for error at peak hours. We build management systems that put the right information in front of the right person at the right moment, from patient admission to kitchen ticket.', '[{"value":"30-40%","label":"less time spent on registration, billing and end of day paperwork"},{"value":"1 record","label":"per patient or per order, visible to every department that needs it"},{"value":"24/7","label":"monitored uptime with a named on call engineer"}]'::jsonb, array['Front desk, clinical staff and billing each keep their own version of the same record.', 'Patients or guests wait because staff are searching for information.', 'Kitchen tickets are lost or delayed between the floor and the line during a rush.', 'You cannot see occupancy, wait times, food cost or revenue by location without building a spreadsheet.', 'Your current software vendor charges for every change and takes months to deliver it.']::text[], '[{"title":"Hospital: patient administration","body":"Registration, appointments, admissions, bed management and discharge, with one patient record across departments."},{"title":"Hospital: clinical and billing modules","body":"Electronic medical records, lab and pharmacy orders, insurance claims and invoicing, with HL7 and FHIR interfaces to existing lab and imaging systems."},{"title":"Restaurant: front of house","body":"Table management, reservations, ordering by server tablet or QR code, and integrated POS and payments."},{"title":"Restaurant: kitchen and stock","body":"Kitchen display screens, recipe costing, inventory, supplier orders and wastage tracking."},{"title":"Multi-site reporting","body":"Dashboards for occupancy, wait times, sales, food cost and labour by location, updated live."},{"title":"Roles, audit and security","body":"Role based access, a full audit log of who viewed or changed a record, encryption at rest and in transit."}]'::jsonb, '[{"title":"Shadow","body":"We spend days on your floor during real shifts and document each handoff between people and departments."},{"title":"Design with staff","body":"Nurses, front desk, servers and kitchen leads review prototypes. Screens are designed for people who are busy and standing up."},{"title":"Build and pilot","body":"One ward or one location goes first. We measure the time each task takes before and after."},{"title":"Roll out and support","body":"Site by site rollout with training on each shift, followed by 24/7 monitored support."}]'::jsonb, array['.NET', 'Node.js', 'React', 'React Native', 'PostgreSQL', 'SQL Server', 'HL7', 'FHIR', 'Redis', 'Azure', 'AWS', 'Power BI']::text[], '{"timeline":"Pilot ward or location live in 4 to 6 months","team":"5 to 9 people: solution architect, domain analyst, engineers, QA, trainer","model":"Phased fixed price per module, with a 24/7 support agreement"}'::jsonb, '[{"q":"How do you protect patient data?","a":"Systems are built to PHIPA, PIPEDA and HIPAA requirements as they apply to you: role based access, audit logs of every record view, encryption at rest and in transit, and hosting in a Canadian region when required. We complete a privacy impact assessment with your privacy officer."},{"q":"Can it connect to our existing lab, imaging or accounting systems?","a":"Yes. We integrate through HL7 v2 and FHIR for clinical systems, and through APIs for accounting, payroll and delivery platforms. Integration points are listed and tested during discovery."},{"q":"How do you migrate from our current system?","a":"Patient, menu, inventory and financial data are extracted, cleaned and loaded in trial runs first. Staff verify samples from each run. The final migration happens during your quietest hours with a rollback plan."},{"q":"What does it cost?","a":"Cost depends on the number of modules, sites, integrations and the volume of legacy data. We price by module so you can begin with the area causing the most pain and add the rest later."},{"q":"What support do you provide after go live?","a":"A support agreement with response times in writing: 15 minutes for a system down incident, at any hour. You have a named on call engineer and a monthly review of uptime and open requests."}]'::jsonb, array['healthcare', 'restaurants-hospitality']::text[], array['hospital-management-system', 'restaurant-group-pos-rollout']::text[], 'Hospital and Restaurant Management Software Development', 'Custom hospital management systems and restaurant management software. Patient administration, EMR, billing, kitchen display, inventory and multi-site reporting with 24/7 support.')
insert into public.industries
  (slug, position, published, icon, name, tagline, summary, hero_title, hero_lead, stats, challenges, solutions, compliance, services, case_studies, faqs, seo_title, seo_description)
values
  ('healthcare', 10, true, 'healthcare', 'Healthcare', 'Hospital management, patient portals and clinical workflows.', 'Software for hospitals, clinics and health technology companies. We build systems that reduce administrative load on clinical staff and keep patient data protected under PHIPA, PIPEDA and HIPAA.', 'Software that gives clinicians time back and keeps patient data protected.', 'Clinical staff lose hours each shift to duplicate entry and systems that do not share a record. We build hospital management systems, patient portals and integrations that follow the way care is delivered, with privacy controls your privacy officer can audit.', '[{"value":"30-40%","label":"less administrative time at registration and discharge"},{"value":"100%","label":"of record access logged and auditable"},{"value":"15 min","label":"response time for system down incidents, at any hour"}]'::jsonb, '[{"title":"Fragmented patient records","body":"Registration, clinical notes, lab results and billing sit in separate systems, so staff re-enter data and chase information by phone."},{"title":"Privacy obligations","body":"PHIPA, PIPEDA and HIPAA require access controls, audit trails and breach procedures that many legacy systems cannot demonstrate."},{"title":"Legacy integrations","body":"Lab, imaging and pharmacy systems speak HL7 v2, and connecting them to anything modern takes specialist knowledge."},{"title":"Staff adoption","body":"Clinicians reject software that adds clicks. A system that is not used at the bedside does not improve care."}]'::jsonb, '[{"title":"Hospital management systems","body":"Admissions, bed management, appointments, EMR, pharmacy, lab orders and billing on one patient record."},{"title":"Patient portals and apps","body":"Online booking, results, prescriptions and secure messaging on web, iOS and Android, built to WCAG 2.2 AA."},{"title":"Interoperability","body":"HL7 v2 and FHIR interfaces between your existing lab, imaging and provincial systems."},{"title":"AI for administration","body":"Assistants for appointment enquiries and automation for referral intake and claims, with clinical decisions left to clinicians."}]'::jsonb, array['PHIPA', 'PIPEDA', 'HIPAA', 'HL7 v2 and FHIR', 'SOC 2 Type II', 'WCAG 2.2 AA']::text[], array['management-software', 'mobile-app-development', 'ai-automation', 'full-stack-development']::text[], array['hospital-management-system']::text[], '[{"q":"Where is patient data hosted?","a":"In the region your regulations require. For Canadian providers we host in Canadian data centres on AWS or Azure. Data is encrypted in transit and at rest, and production access is limited to named engineers with logged sessions."},{"q":"Do your engineers access real patient data during development?","a":"No. Development and testing use synthetic or de-identified data. Production access is granted only for support incidents, with approval from your team and a full audit record."},{"q":"Can you integrate with our existing EMR or lab system?","a":"Yes. We build HL7 v2 and FHIR interfaces and have experience with integration engines such as Mirth Connect. Each interface is specified and tested with your vendor before go live."},{"q":"How do you train clinical staff?","a":"Training runs on each shift, in short sessions on the ward, with super users appointed in every department. Engineers stay on call through the first weeks of use."}]'::jsonb, 'Healthcare Software Development', 'Healthcare software development: hospital management systems, patient portals and HL7 and FHIR integrations built to PHIPA, PIPEDA and HIPAA requirements.'),
  ('restaurants-hospitality', 20, true, 'restaurant', 'Restaurants and Hospitality', 'POS, kitchen display, ordering and multi-branch reporting.', 'Software for restaurant groups, cafes, hotels and franchises. We build POS, kitchen display, online ordering and reporting systems that hold up during a Friday night rush and show head office the numbers live.', 'Systems that hold up on a Friday night and report to head office by Saturday morning.', 'Margins in hospitality are thin and service windows are short. We build POS, kitchen display, ordering and inventory systems that keep tickets moving when the internet drops, and give owners live sales, food cost and labour figures across every location.', '[{"value":"100%","label":"of orders captured during internet outages"},{"value":"2-4 pts","label":"typical reduction in food cost percentage with recipe level tracking"},{"value":"Live","label":"sales and labour figures across all branches"}]'::jsonb, '[{"title":"Outages at peak hours","body":"A cloud only POS that loses connection during service means handwritten tickets, lost sales and an angry floor."},{"title":"Delivery platform fees and tablet clutter","body":"Each delivery service brings its own tablet, its own menu and a commission of up to 30 percent."},{"title":"No view of food cost","body":"Without recipe level inventory, wastage and over-portioning stay invisible until the monthly accounts."},{"title":"Inconsistent branches","body":"Menus, prices and promotions drift between locations when each is updated by hand."}]'::jsonb, '[{"title":"Custom POS and payments","body":"Offline first tills and server tablets, split bills, tips and your choice of payment processor."},{"title":"Kitchen display and routing","body":"Orders routed to the right station with timers, so the pass sees every ticket in order."},{"title":"Direct ordering and loyalty","body":"Your own web and mobile ordering with loyalty, plus delivery platform orders merged into one queue."},{"title":"Inventory and head office reporting","body":"Recipe costing, supplier orders, wastage and live reports by branch, with central menu and price control."}]'::jsonb, array['PCI DSS', 'PIPEDA', 'CASL for marketing messages', 'WCAG 2.2 AA', 'Provincial sales tax and HST rules']::text[], array['custom-pos-systems', 'management-software', 'mobile-app-development', 'ai-chatbots']::text[], array['restaurant-group-pos-rollout']::text[], '[{"q":"What happens when the internet goes down mid service?","a":"Tills, tablets and kitchen screens keep working on the local network. Orders, payments and stock movements are stored on site and synced to the cloud when the connection returns."},{"q":"Can you integrate delivery platforms?","a":"Yes. Orders from the major delivery services are pulled into the same kitchen queue and the same sales reports, so staff work from one screen."},{"q":"Can we roll out one location at a time?","a":"That is how we recommend doing it. A pilot site runs for two to four weeks, feedback is built in, then remaining locations go live in waves with support during each first week."}]'::jsonb, 'Restaurant and Hospitality Software Development', 'Restaurant software development: custom POS, kitchen display systems, online ordering, inventory and multi-branch reporting that keeps working offline.'),
  ('retail-ecommerce', 30, true, 'retail', 'Retail and E-commerce', 'Unified inventory, storefronts and in-store point of sale.', 'Software for retailers selling in store and online. We build storefronts, POS and inventory systems that share one stock count and one customer record across every channel.', 'One stock count and one customer record, in store and online.', 'Retailers lose sales when the website shows stock the shop sold an hour ago, and lose customers when a page takes four seconds to load. We build fast storefronts, connected POS and inventory systems that keep every channel in agreement.', '[{"value":"< 2.0s","label":"storefront load time target on mobile"},{"value":"1 inventory","label":"shared by stores, warehouse and online channels"},{"value":"99.95%","label":"uptime target through peak season"}]'::jsonb, '[{"title":"Overselling and stockouts","body":"Online and in-store stock are counted separately, so customers order items that are already gone."},{"title":"Slow storefronts","body":"Every extra second of load time on mobile reduces conversion, and themes loaded with plugins get slower each year."},{"title":"Peak season failures","body":"Checkout errors on Black Friday cost more than the entire year of hosting."},{"title":"Disconnected customer data","body":"Loyalty, purchase history and marketing consent live in different tools, so offers miss the mark."}]'::jsonb, '[{"title":"Headless storefronts","body":"Next.js front ends on Shopify, commercetools or a custom back end, built to pass Core Web Vitals."},{"title":"Retail POS","body":"In-store tills connected to the same catalogue, prices and stock as the website."},{"title":"Inventory and order management","body":"Real time stock across locations, ship from store, click and collect and returns."},{"title":"Customer service automation","body":"AI assistants for order status, returns and product questions, with handover to staff."}]'::jsonb, array['PCI DSS', 'PIPEDA', 'CASL', 'GDPR for EU customers', 'WCAG 2.2 AA', 'AODA']::text[], array['frontend-development', 'custom-pos-systems', 'full-stack-development', 'ai-chatbots']::text[], array['retail-storefront-rebuild']::text[], '[{"q":"Do we have to leave Shopify?","a":"No. A headless build keeps Shopify for catalogue, checkout and payments and replaces only the front end. You keep the admin your team knows and gain the speed and design control."},{"q":"How do you prepare for peak traffic?","a":"We load test at three times your previous peak, set up autoscaling and caching, and agree a change freeze before key dates. Engineers are on call through the peak period."},{"q":"Can you connect our POS, ERP and online store?","a":"Yes. We integrate stock, orders, prices and customers across systems through APIs, with reconciliation reports that flag any mismatch."}]'::jsonb, 'Retail and E-commerce Software Development', 'Retail and e-commerce development: headless storefronts in Next.js, connected POS and unified inventory and order management across every channel.'),
  ('fintech', 40, true, 'finance', 'Financial Services', 'Secure platforms, reconciliations and client onboarding.', 'Software for lenders, payment companies, wealth managers and insurers. We build secure platforms and automations that pass security reviews and reduce the cost of onboarding, servicing and reconciliation.', 'Financial software that passes the security review and the audit.', 'In financial services a defect is a regulatory event. We build lending platforms, client portals, onboarding flows and reconciliation engines with security controls documented from the first sprint, so your auditors and partner banks get the evidence they ask for.', '[{"value":"Minutes","label":"to onboard a client with automated identity checks"},{"value":"100%","label":"of transactions reconciled automatically or flagged"},{"value":"SOC 2","label":"aligned controls in every environment we build"}]'::jsonb, '[{"title":"Slow onboarding","body":"Manual identity checks and document review take days, and applicants leave for a competitor that approves in minutes."},{"title":"Security and audit pressure","body":"Partner banks, regulators and enterprise clients expect SOC 2 reports, penetration tests and evidence for every control."},{"title":"Manual reconciliation","body":"Finance teams match bank files, processor reports and ledgers in spreadsheets, and breaks surface days later."},{"title":"Legacy cores","body":"Core banking and policy systems are hard to change, so new products wait behind long release cycles."}]'::jsonb, '[{"title":"Digital onboarding and KYC","body":"Identity verification, document capture and risk scoring integrated with providers such as Persona, Onfido or Trulioo."},{"title":"Lending and servicing platforms","body":"Origination, decisioning, disbursement, collections and borrower portals."},{"title":"Reconciliation and reporting","body":"Automated matching across banks, processors and ledgers, with exception queues and regulatory reports."},{"title":"AI support and document processing","body":"Assistants that answer from approved policy content, and extraction of statements and applications with full audit trails."}]'::jsonb, array['SOC 2 Type II', 'PCI DSS', 'PIPEDA', 'FINTRAC AML and KYC requirements', 'OSFI B-13', 'ISO 27001']::text[], array['full-stack-development', 'ai-chatbots', 'ai-automation', 'frontend-development']::text[], array['lender-ai-support-assistant']::text[], '[{"q":"How do you handle security during development?","a":"Engineers work on managed devices with single sign on and least privilege access. Code is scanned for vulnerabilities and secrets on every commit, dependencies are monitored, and each release passes a security checklist. We support third party penetration tests before launch."},{"q":"Can you work under our compliance programme?","a":"Yes. We sign your NDA and data processing agreements, follow your change management process and provide evidence for SOC 2 and ISO 27001 audits."},{"q":"Do you keep data in Canada?","a":"When required, yes. Production environments are deployed in Canadian cloud regions, and we document data flows so you can show where each data element is stored and processed."},{"q":"Can AI be used safely with regulated customer communication?","a":"With limits. Assistants answer only from approved content, cite sources, avoid advice and escalate regulated topics to licensed staff. Every conversation is logged for review."}]'::jsonb, 'Fintech and Financial Services Software Development', 'Financial services software development: onboarding and KYC, lending platforms, reconciliation and AI support built to SOC 2, PCI DSS and FINTRAC requirements.'),
  ('logistics', 50, true, 'logistics', 'Logistics and Supply Chain', 'Dispatch, tracking and warehouse operations.', 'Software for carriers, couriers, freight brokers and warehouses. We build dispatch systems, driver apps and tracking portals that cut phone calls and give customers a delivery time they can trust.', 'Know where every load is without picking up the phone.', 'Dispatchers spend their day calling drivers, and customers call dispatchers. We build driver apps, dispatch boards, tracking portals and warehouse tools that share one live picture, including in areas with no signal.', '[{"value":"50-70%","label":"fewer status calls to dispatch after live tracking"},{"value":"Same day","label":"invoicing with electronic proof of delivery"},{"value":"Offline","label":"driver app keeps working without coverage"}]'::jsonb, '[{"title":"No live visibility","body":"Status lives in drivers'' heads and dispatchers'' notebooks, so every customer question becomes a phone call."},{"title":"Paper proof of delivery","body":"Signed paperwork returns days later, delaying invoices and inviting disputes."},{"title":"Manual planning","body":"Routes and loads are planned from experience and spreadsheets, leaving empty kilometres and missed windows."},{"title":"Disconnected systems","body":"TMS, WMS, telematics and accounting do not share data, so the same shipment is entered several times."}]'::jsonb, '[{"title":"Driver mobile apps","body":"Job lists, navigation, scanning, photos and signatures, working offline and syncing on reconnect."},{"title":"Dispatch and route planning","body":"Live boards, automated assignment and route optimisation against delivery windows and vehicle capacity."},{"title":"Customer tracking portals","body":"Live status, estimated arrival and documents, with notifications by SMS and email."},{"title":"Warehouse and integration","body":"Barcode driven receiving, picking and dispatch, with EDI and API links to customers, carriers and telematics."}]'::jsonb, array['ELD mandate (Canada and US)', 'PIPEDA', 'EDI X12 (204, 210, 214)', 'SOC 2', 'CBSA ACI eManifest']::text[], array['mobile-app-development', 'full-stack-development', 'erp-development', 'ai-automation']::text[], array['logistics-driver-app']::text[], '[{"q":"Will drivers actually use the app?","a":"They do when it saves them time. We design with drivers, keep the main flow to a few taps, and make it work with gloves, in sunlight and without signal. Adoption is measured during the pilot."},{"q":"Can you integrate with our TMS and telematics?","a":"Yes. We connect to common TMS platforms, telematics providers such as Samsara and Geotab, and customer systems through API and EDI."},{"q":"Do you build route optimisation?","a":"We integrate proven optimisation engines and tune them to your constraints: time windows, vehicle types, driver hours and priorities. Dispatchers keep the ability to override."}]'::jsonb, 'Logistics and Supply Chain Software Development', 'Logistics software development: driver apps, dispatch and route planning, tracking portals and warehouse systems with EDI and telematics integration.'),
  ('real-estate', 60, true, 'realestate', 'Real Estate', 'Listings, CRM and property management portals.', 'Software for brokerages, developers and property managers. We build listing platforms, CRMs and tenant portals that respond to leads in minutes and take rent, maintenance and leasing off paper.', 'Respond to every lead in minutes and run every property from one screen.', 'The first agent to respond usually wins the client, and the property manager with the fewest manual steps keeps the margin. We build listing platforms, CRMs and tenant and owner portals connected to MLS feeds, payments and accounting.', '[{"value":"< 5 min","label":"lead response time with automated routing and follow up"},{"value":"90%+","label":"of rent collected online through tenant portals"},{"value":"1 portal","label":"for tenants, owners and maintenance teams"}]'::jsonb, '[{"title":"Slow lead response","body":"Enquiries from portals, the website and social channels land in different inboxes and wait hours for a reply."},{"title":"Paper heavy leasing","body":"Applications, screening, leases and deposits involve printing, scanning and chasing signatures."},{"title":"Maintenance by phone and email","body":"Requests are lost, tenants call repeatedly and owners see no record of what was done."},{"title":"Generic listing sites","body":"Template websites load slowly, rank poorly and look the same as every competitor."}]'::jsonb, '[{"title":"Listing platforms","body":"Fast property search with map views, saved searches and MLS and IDX integration."},{"title":"CRM and lead automation","body":"Leads captured from every source, routed to the right agent and followed up automatically."},{"title":"Tenant and owner portals","body":"Online applications, e-signature, rent payments, maintenance requests and owner statements."},{"title":"AI assistants","body":"Round the clock answers to listing questions and showing bookings, with qualified leads passed to agents."}]'::jsonb, array['PIPEDA', 'CASL', 'RECO and provincial advertising rules', 'CREA DDF and MLS data policies', 'PCI DSS', 'WCAG 2.2 AA']::text[], array['full-stack-development', 'frontend-development', 'mobile-app-development', 'ai-chatbots']::text[], '{}'::text[], '[{"q":"Can you integrate MLS listings?","a":"Yes. We integrate CREA DDF, regional board feeds and IDX and RESO Web API sources, and follow each board''s display rules."},{"q":"Can tenants pay rent through the portal?","a":"Yes. We integrate pre-authorised debit, card and Interac options through a payment processor, with receipts and ledger entries posted automatically."},{"q":"Does it connect to our accounting software?","a":"Yes. Rent, fees and owner disbursements sync to QuickBooks, Xero, Yardi or your existing property accounting system."}]'::jsonb, 'Real Estate Software Development', 'Real estate software development: listing platforms with MLS integration, CRM and lead automation, and tenant and owner portals with online payments.'),
  ('education', 70, true, 'education', 'Education', 'Learning platforms and school administration systems.', 'Software for schools, colleges, training providers and education technology companies. We build learning platforms and administration systems that work on any device and protect student data.', 'Learning platforms students use and administrators can run.', 'Education software has to serve a 9 year old on a shared tablet and a registrar closing the term. We build learning platforms, student information systems and admissions portals that are accessible, dependable in exam week and careful with student data.', '[{"value":"WCAG 2.2 AA","label":"accessibility on every learner facing screen"},{"value":"10x","label":"normal traffic load tested before enrolment and exam periods"},{"value":"1 login","label":"across LMS, SIS and library through single sign on"}]'::jsonb, '[{"title":"Peak load failures","body":"Platforms that run well all term fail on enrolment day and during exams, when they matter most."},{"title":"Too many logins","body":"Students and staff move between an LMS, a student system, payment pages and email with separate accounts."},{"title":"Accessibility requirements","body":"AODA and similar laws require accessible digital content, and many platforms fall short."},{"title":"Manual administration","body":"Admissions, timetabling, fees and transcripts depend on spreadsheets and re-keyed forms."}]'::jsonb, '[{"title":"Learning platforms","body":"Courses, live classes, assessments and progress tracking on web and mobile, with offline access to materials."},{"title":"Student information systems","body":"Admissions, enrolment, attendance, grading, fees and transcripts in one system."},{"title":"Integrations and single sign on","body":"LTI 1.3, SCORM, xAPI and SSO with Google Workspace and Microsoft Entra ID."},{"title":"AI study and support assistants","body":"Assistants that answer from course material and school policy, with safeguards suited to younger users."}]'::jsonb, array['FIPPA and MFIPPA', 'PIPEDA', 'FERPA', 'COPPA', 'AODA and WCAG 2.2 AA', 'LTI 1.3']::text[], array['full-stack-development', 'mobile-app-development', 'frontend-development', 'ai-chatbots']::text[], '{}'::text[], '[{"q":"Can you extend an existing LMS such as Moodle or Canvas?","a":"Yes. We build LTI tools, plugins and integrations for existing platforms, and recommend a custom platform only when your teaching model does not fit a standard LMS."},{"q":"How do you protect student data?","a":"Data is hosted in the region your regulations require, access is role based and logged, and we collect only what is needed. We work with your privacy office on FIPPA, FERPA and COPPA obligations."},{"q":"Will it cope with exam week?","a":"We load test at ten times normal traffic before each peak period, configure autoscaling and keep engineers on call during exams and enrolment."}]'::jsonb, 'Education Software Development', 'Education software development: learning platforms, student information systems and admissions portals with LTI integration, single sign on and WCAG 2.2 AA accessibility.'),
  ('manufacturing', 80, true, 'manufacturing', 'Manufacturing', 'Production planning, quality control and ERP.', 'Software for manufacturers and distributors. We build ERP, production planning and shop floor systems that connect orders, materials and machines, so you know your true cost and delivery date for every job.', 'Know the true cost and delivery date of every job on the floor.', 'When planning lives in spreadsheets and the shop floor reports on paper, nobody can say what a job cost until weeks after it ships. We build ERP, planning and shop floor systems that connect sales orders to materials, machines and labour in real time.', '[{"value":"5 days","label":"typical month end close, down from 12 to 15"},{"value":"98%+","label":"inventory accuracy with barcode driven stock movements"},{"value":"Live","label":"job costing across materials, labour and machine time"}]'::jsonb, '[{"title":"Planning in spreadsheets","body":"Production schedules are rebuilt by hand whenever an order changes, and material shortages appear on the day."},{"title":"Inaccurate inventory","body":"Stock moves without being recorded, so purchasing over-orders and production still runs short."},{"title":"No real job costing","body":"Labour and machine time are estimated, so margin by product is a guess."},{"title":"Quality records on paper","body":"Inspection results and traceability data sit in binders, which makes audits and recalls slow."}]'::jsonb, '[{"title":"Manufacturing ERP","body":"Sales, purchasing, bills of materials, MRP, inventory and finance in one system, on Odoo, ERPNext or Dynamics 365."},{"title":"Shop floor data capture","body":"Tablets and scanners at each work centre to record time, quantities and scrap as they happen."},{"title":"Quality and traceability","body":"Inspection plans, non-conformance tracking and lot traceability from raw material to shipment."},{"title":"Automation and reporting","body":"Automated purchase order and invoice processing, plus dashboards for OEE, on time delivery and margin."}]'::jsonb, array['ISO 9001', 'ISO 27001', 'CSA and UL documentation requirements', 'EDI X12 (850, 856, 810)', 'PIPEDA', 'SOC 2']::text[], array['erp-development', 'ai-automation', 'full-stack-development', 'mobile-app-development']::text[], array['distributor-erp-migration']::text[], '[{"q":"Can the ERP connect to machines on the floor?","a":"Yes. We collect data from PLCs and machines through OPC UA and MQTT, or through operator tablets where machines are older. The level of connection is decided by what the data is worth to you."},{"q":"How do you avoid disrupting production during go live?","a":"Old and new systems run in parallel for a full accounting period, cutover happens on a weekend or shutdown, and engineers are on site or on call for the first week."},{"q":"Do you support EDI with our customers and suppliers?","a":"Yes. We implement X12 and EDIFACT documents such as purchase orders, ship notices and invoices through your VAN or direct AS2 connections."}]'::jsonb, 'Manufacturing Software and ERP Development', 'Manufacturing software development: ERP with MRP, shop floor data capture, quality and traceability, and live job costing for manufacturers and distributors.')
insert into public.case_studies
  (slug, position, published, client, title, summary, industry, services, location, year, duration, team, featured, tone, hero_metric, metrics, challenge, approach, solution, results, stack, quote, seo_title, seo_description)
values
  ('restaurant-group-pos-rollout', 10, true, 'Restaurant group, 14 locations, Ontario', 'One point of sale across 14 restaurants, live in 11 weeks', 'A restaurant group replaced three ageing POS products with one offline-first system. Order times fell, month-end closed four days sooner and head office finally saw every branch on one screen.', 'restaurants-hospitality', array['custom-pos-systems', 'management-software']::text[], 'Ontario, Canada', '2026', '11 weeks to first branch, 19 weeks to all 14', '5 engineers, 1 designer, 1 delivery manager', true, 'lime', '{"value":"38%","label":"faster order to kitchen time"}'::jsonb, '[{"value":"38%","label":"faster order to kitchen time at peak"},{"value":"4 days","label":"removed from month-end close"},{"value":"0","label":"sales lost to internet outages since launch"},{"value":"14","label":"branches on one menu and one report"}]'::jsonb, array['The group had grown by acquisition. Each cluster of branches ran a different point of sale, with its own menu codes, tax setup and reporting format.', 'Finance staff spent the first week of every month merging spreadsheets by hand. Two branches lost card sales during a four hour internet outage because their terminals could not take orders offline.', 'The licence renewal on the largest system was due in five months. Leadership wanted one system in place before signing anything.']::text[], '[{"title":"Two weeks on the floor before any code","body":"An engineer and a designer shadowed a Friday dinner service at three branches. We timed every tap from order to kitchen ticket and found that modifiers caused 60% of the delay."},{"title":"Offline first by design","body":"Each terminal keeps a local SQLite database and syncs to the server when a connection exists. Orders, kitchen tickets and cash payments keep working with the router unplugged."},{"title":"One pilot branch, then waves of four","body":"The busiest branch went first so the hardest case was proven early. The remaining 13 followed in waves, each with an engineer on site for opening night."},{"title":"A single menu owned by head office","body":"Menu items, prices and taxes are edited once and published to selected branches. Branch managers can mark items sold out but cannot change prices."}]'::jsonb, array['Tablet POS for servers and counter staff, built in React Native with a local database on every device.', 'Kitchen display screens that route items by station and show the age of each ticket.', 'A head office console for menus, staff permissions, discounts and branch comparisons.', 'Nightly export to the group''s accounting package, mapped to their existing chart of accounts.']::text[], array['Median order to kitchen time at peak dropped from 94 seconds to 58 seconds.', 'Month-end close moved from nine working days to five.', 'Three internet outages have occurred since launch. No orders or payments were lost in any of them.', 'Licence costs fell by 41% a year compared with renewing the three old systems.']::text[], array['React Native', 'TypeScript', 'SQLite', 'Node.js', 'PostgreSQL', 'AWS', 'Stripe Terminal']::text[], '{"text":"For the first time I can open one report on Monday morning and trust it. The outage test on opening night is what convinced my managers.","role":"Director of Operations, restaurant group"}'::jsonb, 'Case Study: Custom POS Rollout Across 14 Restaurants', 'How a 14 location restaurant group replaced three POS products with one offline-first system in 11 weeks and cut order to kitchen time by 38%.'),
  ('hospital-management-system', 20, true, 'Private hospital, 220 beds, Dubai', 'A 220 bed hospital moves from paper files to one patient record', 'We built a hospital management system covering registration, wards, pharmacy, lab and billing. Patients wait less at the front desk and discharge bills are ready the same hour.', 'healthcare', array['management-software', 'full-stack-development']::text[], 'Dubai, UAE', '2025', '7 months, released in 4 phases', '7 engineers, 1 designer, 1 QA lead, 1 delivery manager', true, 'ink', '{"value":"52%","label":"shorter front desk wait"}'::jsonb, '[{"value":"52%","label":"shorter wait at registration"},{"value":"45 min","label":"average discharge billing, down from 3 hours"},{"value":"99.95%","label":"uptime over the first 12 months"},{"value":"640","label":"staff trained and using the system daily"}]'::jsonb, array['Patient files were paper. Pharmacy, lab and billing each ran separate software that did not share a patient ID.', 'A discharge needed a clerk to walk between four departments collecting charges. Families waited about three hours for a final bill.', 'The hospital had tried an off the shelf product two years earlier. Staff abandoned it within three months because it did not match how wards actually worked.']::text[], '[{"title":"Department by department, never all at once","body":"Registration and outpatient went live first. Wards, pharmacy and lab followed, then billing. Each phase ran alongside the old process for two weeks before cutover."},{"title":"Nurses and clerks tested every screen","body":"We ran weekly sessions with 12 staff from different shifts. Screens that needed more than three taps for a routine task were redesigned."},{"title":"Access control and audit from day one","body":"Every read and write of a patient record is logged with user, time and device. Roles limit what each job function can see."},{"title":"On-site support through each cutover","body":"Two engineers sat in the hospital for the first ten days of every phase, covering day and night shifts."}]'::jsonb, array['One patient record with a single ID across outpatient, inpatient, pharmacy, lab and billing.', 'Ward boards showing bed occupancy, pending orders and expected discharges.', 'Pharmacy stock with batch and expiry tracking, linked to prescriptions.', 'Lab orders and results delivered to the doctor''s worklist, with HL7 interfaces to four analysers.', 'Billing that accrues charges as they happen, so the discharge bill is already complete.']::text[], array['Average registration wait fell from 23 minutes to 11 minutes.', 'Discharge billing takes 45 minutes on average, down from about 3 hours.', 'Pharmacy write-offs for expired stock dropped by 31% in the first year.', 'The system has run at 99.95% uptime across its first 12 months.']::text[], array['Next.js', 'TypeScript', 'NestJS', 'PostgreSQL', 'Redis', 'HL7', 'Docker', 'On-premise and AWS']::text[], '{"text":"The last system was built for a hospital that does not exist. This one was built by people who sat in our wards and watched.","role":"Medical Director, private hospital"}'::jsonb, 'Case Study: Hospital Management System for a 220 Bed Hospital', 'A 220 bed private hospital replaced paper files and four disconnected tools with one hospital management system. Registration waits fell by 52%.'),
  ('distributor-erp-migration', 30, true, 'Industrial parts manufacturer and distributor, 3 warehouses', 'Replacing a 17 year old ERP without stopping a single shipment', 'A manufacturer moved finance, inventory, purchasing and production planning to a custom ERP. The cutover happened over one weekend and Monday''s orders shipped on time.', 'manufacturing', array['erp-development']::text[], 'Alberta, Canada', '2026', '9 months', '6 engineers, 1 business analyst, 1 delivery manager', true, 'sand', '{"value":"99.2%","label":"inventory accuracy, up from 86%"}'::jsonb, '[{"value":"99.2%","label":"inventory accuracy, up from 86%"},{"value":"0","label":"shipping days lost during cutover"},{"value":"27%","label":"less stock held for the same fill rate"},{"value":"1.2M","label":"historical records migrated and reconciled"}]'::jsonb, array['The existing ERP was 17 years old and ran on a server the vendor no longer supported. Only one employee knew how to maintain it.', 'Stock counts in the system matched the shelves 86% of the time. Sales staff phoned the warehouse to confirm availability before quoting.', 'The company ships every working day. A cutover that paused dispatch for even 48 hours would breach supply contracts.']::text[], '[{"title":"Map the real process, not the manual","body":"Our analyst spent three weeks with finance, purchasing and warehouse leads. We documented 46 workflows and retired 11 that existed only because of the old system''s limits."},{"title":"Migrate the data three times before it counted","body":"We ran three full rehearsal migrations. Each one was reconciled against the old system to the cent and to the unit, and each surfaced fewer exceptions."},{"title":"Run both systems in parallel for a month","body":"For four weeks every transaction was entered in both systems. Differences were reviewed daily until there were none for ten days in a row."},{"title":"Cut over on a long weekend with a rollback plan","body":"The switch ran from Friday evening to Sunday afternoon. A tested rollback was ready and was not needed."}]'::jsonb, array['Finance with general ledger, payables, receivables and multi-entity consolidation.', 'Inventory across three warehouses with barcode scanning on handheld devices.', 'Purchasing with reorder points calculated from 24 months of demand.', 'Production planning tied to bills of materials and machine capacity.', 'Dashboards for the leadership team, refreshed every 15 minutes.']::text[], array['Inventory accuracy rose from 86% to 99.2% within four months of go-live.', 'Monday''s orders after cutover shipped on schedule. No shipping days were lost.', 'Stock on hand fell by 27% while the order fill rate held at 97%.', 'The company no longer depends on one person or one unsupported server.']::text[], array['React', 'TypeScript', '.NET 8', 'SQL Server', 'Azure', 'Power BI', 'Zebra handheld scanners']::text[], '{"text":"I expected a bad month. We had a quiet weekend and a normal Monday. The three rehearsal migrations were worth every hour.","role":"Chief Financial Officer, industrial distributor"}'::jsonb, 'Case Study: ERP Migration for a Manufacturer and Distributor', 'How an industrial manufacturer replaced a 17 year old ERP with a custom system in 9 months, with zero shipping days lost and 99.2% inventory accuracy.'),
  ('lender-ai-support-assistant', 40, true, 'Consumer lender, 180,000 active customers', 'An AI assistant that resolves 61% of support chats and knows when to stop', 'A regulated lender added an AI assistant to its support channels. It answers from approved policy documents and live account data, and hands over to a person when a question touches hardship or complaints.', 'fintech', array['ai-chatbots', 'ai-automation']::text[], 'British Columbia, Canada', '2026', '14 weeks', '4 engineers, 1 designer, 1 delivery manager', false, 'sage', '{"value":"61%","label":"of chats resolved without an agent"}'::jsonb, '[{"value":"61%","label":"of chats resolved without an agent"},{"value":"9 sec","label":"median first response, down from 6 minutes"},{"value":"4.6 / 5","label":"customer rating for assistant conversations"},{"value":"0","label":"compliance findings in the first audit"}]'::jsonb, array['Support volume had doubled in 18 months. Customers waited six minutes for a first reply and about a third of chats asked the same 20 questions.', 'As a regulated lender, the company could not allow an assistant to guess. Every answer about fees, rates or repayment had to match approved wording.', 'An earlier rules-based bot had a 12% resolution rate and customers had learned to type ''agent'' immediately.']::text[], '[{"title":"Answers come only from approved sources","body":"The assistant retrieves from 340 policy and product documents signed off by compliance. If no source supports an answer, it says so and offers a person."},{"title":"Test set before launch, not after","body":"We built 1,200 test conversations from real transcripts with compliance staff grading the answers. Nothing shipped until accuracy passed 97%."},{"title":"Hard handover rules","body":"Mentions of financial hardship, complaints, fraud or bereavement go straight to a trained agent with the full conversation attached."},{"title":"Staged exposure","body":"The assistant started on 5% of chats. Exposure rose weekly as quality metrics held, reaching 100% in week six."}]'::jsonb, array['Chat assistant on web and mobile, authenticated against the customer''s account.', 'Read access to balances, payment dates and statements through the lender''s existing API.', 'Automated handling of four requests end to end: payment date change, statement copy, payoff quote and address update.', 'Agent workspace that shows the assistant''s summary and sources when a chat is handed over.', 'A review console where compliance samples conversations and flags answers for correction.']::text[], array['61% of chats are now resolved without an agent, against 12% for the previous bot.', 'Median first response time fell from 6 minutes to 9 seconds.', 'Agents handle 44% fewer chats and spend that time on hardship and complaint cases.', 'The first compliance audit after launch recorded no findings against the assistant.']::text[], array['Python', 'FastAPI', 'Claude API', 'pgvector', 'PostgreSQL', 'Next.js', 'AWS']::text[], '{"text":"What sold our compliance team was the refusal behaviour. It tells the customer it does not know and gets them a person.","role":"Head of Customer Operations, consumer lender"}'::jsonb, 'Case Study: AI Support Assistant for a Regulated Lender', 'A consumer lender deployed an AI assistant that resolves 61% of support chats from approved sources, with strict handover rules and zero audit findings.'),
  ('logistics-driver-app', 50, true, 'Regional freight carrier, 320 drivers', 'A driver app that ended paper proof of delivery for 320 trucks', 'A freight carrier replaced paper delivery slips with an iOS and Android app. Invoices go out the same day and dispatch sees every truck live.', 'logistics', array['mobile-app-development', 'full-stack-development']::text[], 'Manitoba, Canada', '2025', '16 weeks', '4 engineers, 1 designer, 1 QA engineer', false, 'ink', '{"value":"6 days","label":"faster from delivery to invoice"}'::jsonb, '[{"value":"6 days","label":"faster from delivery to invoice"},{"value":"97%","label":"of drivers active in the first month"},{"value":"72%","label":"fewer ''where is my load'' calls"},{"value":"4.7","label":"average app store rating from drivers"}]'::jsonb, array['Drivers collected signatures on paper and handed slips in at the depot, sometimes a week later. Invoicing could not start until the slip arrived.', 'Dispatchers tracked trucks by phone. Customers called to ask where their load was and dispatch called the driver to find out.', 'Many routes cross areas with no mobile coverage for hours. Any app had to work fully offline.']::text[], '[{"title":"Ride-alongs with drivers","body":"Our designer spent four days in cabs. The app that came out of it has large buttons, works with gloves and needs four taps to complete a delivery."},{"title":"Offline queue with guaranteed delivery","body":"Signatures, photos and status changes are stored on the device and uploaded when coverage returns. Nothing is lost if the phone restarts."},{"title":"Pilot with 25 drivers","body":"A four week pilot on the hardest northern routes produced 38 fixes before the wider release."}]'::jsonb, array['Driver app for iOS and Android with the day''s stops, navigation handoff, signature capture and photo proof.', 'Dispatch web console with live truck positions, exceptions and estimated arrival times.', 'Customer tracking links sent by SMS and email, no login required.', 'Integration with the carrier''s transport management system so a completed stop triggers the invoice.']::text[], array['Average time from delivery to invoice fell from 7 days to under 24 hours.', '311 of 320 drivers were using the app within the first month.', 'Inbound tracking calls to dispatch dropped by 72%.', 'Disputed deliveries fell by more than half because every stop has a timestamped photo and signature.']::text[], array['React Native', 'TypeScript', 'Node.js', 'PostgreSQL', 'Mapbox', 'Firebase Cloud Messaging', 'AWS']::text[], '{"text":"Our drivers are not software people and they did not need to be. Most of them had it figured out before the training session ended.","role":"Vice President of Operations, freight carrier"}'::jsonb, 'Case Study: Driver Mobile App for a 320 Truck Freight Carrier', 'A regional freight carrier replaced paper proof of delivery with an offline-first iOS and Android app, cutting delivery to invoice time by 6 days.'),
  ('retail-storefront-rebuild', 60, true, 'Home goods retailer, 9 stores and online', 'A storefront rebuild that lifted mobile conversion by 34%', 'A home goods retailer had a slow storefront that lost mobile shoppers. We rebuilt the front end in Next.js on their existing commerce platform, with no change to back office operations.', 'retail-ecommerce', array['frontend-development', 'full-stack-development']::text[], 'Quebec, Canada', '2026', '10 weeks', '3 engineers, 1 designer', false, 'lime', '{"value":"34%","label":"higher mobile conversion rate"}'::jsonb, '[{"value":"34%","label":"higher mobile conversion rate"},{"value":"1.4 sec","label":"Largest Contentful Paint, down from 5.8"},{"value":"22%","label":"more organic search sessions in 90 days"},{"value":"100%","label":"WCAG 2.1 AA pages in the checkout flow"}]'::jsonb, array['71% of traffic was mobile but mobile converted at less than half the desktop rate. Product pages took 5.8 seconds to show their main image on a 4G connection.', 'The theme had been patched by four agencies over six years. Small changes took weeks and often broke checkout.', 'The retailer did not want to replace its commerce platform, inventory system or fulfilment process.']::text[], '[{"title":"Measure first","body":"We instrumented the existing site for two weeks to find where shoppers dropped off. Product pages and the shipping step accounted for 68% of exits."},{"title":"New front end, same back office","body":"The Next.js storefront reads from the existing commerce API. Orders, stock and fulfilment did not change for store staff."},{"title":"Release behind a traffic split","body":"The new storefront took 10% of traffic, then 50%, then 100% over three weeks. Conversion was compared at each step."}]'::jsonb, array['Statically generated category and product pages with incremental updates when price or stock changes.', 'A component library of 42 parts that the retailer''s own team now uses for landing pages.', 'A three step checkout with address lookup and store pickup availability shown per item.', 'Structured data on every product page for rich search results.']::text[], array['Mobile conversion rate rose by 34% against the old site during the split test.', 'Largest Contentful Paint on product pages fell from 5.8 seconds to 1.4 seconds.', 'Organic search sessions grew by 22% in the first 90 days.', 'The retailer''s marketing team now publishes campaign pages without a developer.']::text[], array['Next.js', 'React', 'TypeScript', 'Tailwind CSS', 'Shopify Storefront API', 'Vercel', 'Algolia']::text[], '{"text":"We kept everything that worked behind the counter and replaced the part customers were struggling with. The split test made the decision easy.","role":"Director of E-commerce, home goods retailer"}'::jsonb, 'Case Study: Next.js Storefront Rebuild for a Home Goods Retailer', 'A 9 store home goods retailer rebuilt its storefront in Next.js in 10 weeks. Mobile conversion rose 34% and page load fell from 5.8 to 1.4 seconds.')
insert into public.jobs
  (slug, position, published, title, department, location, type, experience, posted, summary, about, responsibilities, requirements, nice_to_have)
values
  ('senior-full-stack-engineer', 10, true, 'Senior Full Stack Engineer', 'Engineering', 'Remote', 'Full time, hybrid', '6+ years', '2026-11-09', 'Lead the build of client platforms in TypeScript, from database schema to the last pixel. You will own architecture decisions and present them to clients yourself.', array['You will join a team of four to six engineers working on one client product at a time. Current projects include a multi-warehouse ERP and a hospital management system.', 'Senior engineers here speak to clients directly. You will run the weekly demo, explain trade-offs in plain language and write the technical section of proposals.']::text[], array['Design and build features across Next.js front ends and Node.js or NestJS services.', 'Model data in PostgreSQL and write migrations that are safe to run on live systems.', 'Review pull requests daily and hold the team to an agreed standard.', 'Break client requirements into estimates the delivery manager can commit to.', 'Present working software to the client every week.', 'Mentor two mid-level engineers through pairing and written feedback.']::text[], array['Six or more years building production web applications.', 'Strong TypeScript, React and Node.js. You have shipped at least one Next.js application.', 'Solid relational database skills: indexing, query plans, transactions.', 'Experience with automated testing and CI pipelines.', 'Clear written and spoken English. You can explain a technical decision to a non-technical client.', 'Availability during core Eastern Time hours for stand ups, demos and reviews.']::text[], array['Experience with AWS or Azure infrastructure as code.', 'Background in ERP, healthcare or point of sale systems.', 'Open source contributions or technical writing.']::text[]),
  ('react-native-engineer', 20, true, 'React Native Engineer', 'Engineering', 'Remote', 'Full time', '4+ years', '2026-11-02', 'Build iOS and Android apps that work offline, on old devices and in bad coverage. Our mobile work includes driver apps, tablet POS and patient apps.', array['Most of our mobile apps are used by people at work: drivers, servers, nurses. They need speed and reliability more than visual effects.', 'You will work with a designer who does field research and a backend team that builds the sync layer with you.']::text[], array['Build and ship React Native apps to the App Store and Google Play.', 'Implement offline storage and background sync with conflict handling.', 'Write native modules in Swift or Kotlin when the platform requires it.', 'Profile and fix performance problems on low-end Android devices.', 'Set up release pipelines, crash reporting and staged rollouts.']::text[], array['Four or more years of mobile development, at least three in React Native.', 'Two or more apps published under your direct involvement.', 'Working knowledge of Swift or Kotlin.', 'Experience with local databases such as SQLite, WatermelonDB or Realm.', 'Comfort with TypeScript and automated testing on mobile.']::text[], array['Experience integrating payment terminals, barcode scanners or Bluetooth printers.', 'Familiarity with Expo and EAS.', 'Knowledge of accessibility on iOS and Android.']::text[]),
  ('ai-engineer', 30, true, 'AI Engineer', 'Engineering', 'Remote', 'Full time', '4+ years', '2026-11-16', 'Build AI assistants and automations that regulated clients can put in front of customers. The job is 20% prompts and 80% retrieval, evaluation and engineering.', array['Our AI practice builds support assistants, document processing pipelines and internal automations. Clients include lenders and healthcare providers, so accuracy and audit trails matter more than novelty.', 'You will own the evaluation suite for each project. Nothing ships until it passes a test set the client has signed off.']::text[], array['Design retrieval pipelines over client documents and structured data.', 'Build tool-using agents that call client APIs safely, with permission checks and logging.', 'Create evaluation sets from real transcripts and track accuracy across releases.', 'Define handover rules so an assistant stops and routes to a person when it should.', 'Monitor cost, latency and quality in production and report on them weekly.']::text[], array['Four or more years of software engineering in Python or TypeScript.', 'At least one LLM application shipped to real users, with measured results.', 'Hands-on experience with retrieval, embeddings and a vector store such as pgvector.', 'A disciplined approach to evaluation. You can show how you measured quality on a past project.', 'Strong API and backend fundamentals.']::text[], array['Experience in a regulated sector such as finance or healthcare.', 'Workflow automation with n8n, Temporal or similar.', 'Voice or WhatsApp channel integrations.']::text[]),
  ('qa-automation-engineer', 40, true, 'QA Automation Engineer', 'Quality', 'Remote', 'Full time, hybrid', '3+ years', '2026-10-26', 'Own the automated test suites that let us release every week without fear. You will test web, mobile and API layers on systems that businesses run on.', array['QA here starts at the requirements stage. You will read the scope with the engineers and write acceptance tests before the feature is built.', 'Our clients run hospitals, restaurants and warehouses on this software. A missed regression has a real cost, and your work prevents it.']::text[], array['Build and maintain end to end tests in Playwright for web applications.', 'Automate mobile tests with Detox or Maestro.', 'Write API and contract tests that run in CI on every pull request.', 'Design test data and environments that mirror production safely.', 'Run performance tests before major releases and report the findings.', 'Sign off each release with a written summary of coverage and known risks.']::text[], array['Three or more years in test automation.', 'Strong Playwright or Cypress experience and working TypeScript.', 'Experience testing REST APIs and reading SQL.', 'Familiarity with CI systems such as GitHub Actions.', 'Precise written bug reports that an engineer can act on without a call.']::text[], array['Load testing with k6.', 'Accessibility testing against WCAG 2.1 AA.', 'Experience with data migration testing.']::text[]),
  ('product-designer', 50, true, 'Product Designer', 'Design', 'Toronto, Canada or remote', 'Full time, hybrid', '5+ years', '2026-11-12', 'Design software for people who use it eight hours a day. You will spend time in kitchens, wards and warehouses before you open Figma.', array['We design operational software: POS, ERP screens, dispatch consoles, patient records. Success is measured in seconds saved and errors avoided.', 'You will be the only designer on your project, working beside engineers from discovery to launch, with a design lead for critique.']::text[], array['Run discovery: site visits, interviews and workflow mapping with client staff.', 'Produce flows, wireframes and high-fidelity designs in Figma.', 'Test prototypes with real users and change the design based on what you see.', 'Maintain a component library that matches what engineers build.', 'Review builds before each release and log design defects.']::text[], array['Five or more years designing web or mobile products, with shipped work to show.', 'A portfolio that includes complex, data-heavy interfaces.', 'Evidence of research changing your design decisions.', 'Strong Figma skills including components, variables and auto layout.', 'Working understanding of accessibility standards.']::text[], array['Experience designing for tablets, kiosks or handheld scanners.', 'Basic HTML and CSS.', 'Experience presenting to executive stakeholders.']::text[]),
  ('delivery-manager', 60, true, 'Delivery Manager', 'Delivery', 'Toronto, Canada', 'Full time, hybrid', '6+ years', '2026-11-05', 'Be the accountable person for two or three client projects. You hold scope, budget and timeline, and you are the first call when a client has a concern.', array['Delivery managers sit in our Canadian office and work in the client''s time zone. You are the link between the client and the engineering team.', 'We sell fixed scope proposals. Your job is to keep them fixed, or to bring a clear change request to the client before any extra work starts.']::text[], array['Run kickoff, weekly demos and monthly steering meetings with clients.', 'Maintain the project plan, risk log and budget for each engagement.', 'Write change requests with cost and schedule impact.', 'Coordinate with engineering leads on priorities and blockers.', 'Send a written status report to every client each Friday.', 'Support proposals with timelines and staffing plans.']::text[], array['Six or more years managing software delivery, at least three in a client-facing role.', 'A record of fixed scope projects delivered on budget.', 'Enough technical understanding to question an estimate.', 'Excellent written English. Your status reports need no follow-up questions.', 'Experience working with distributed teams across time zones.']::text[], array['Background in ERP or healthcare implementations.', 'PMP or Scrum certification.', 'Experience with Canadian public sector procurement.']::text[])
insert into public.consultation_types
  (slug, position, published, icon, name, duration, summary, description, agenda, host_name, host_role, seo_title, seo_description)
values
  ('project-discovery', 10, true, 'search', 'Project Discovery Call', 30, 'You have something to build. We help you size it, sequence it and price it.', 'A working conversation about the product or system you have in mind. We ask about your users, your deadline and what already exists, then tell you plainly how we would approach it and what it is likely to cost.', array['Your goals, users and deadline', 'What exists today and what must connect to it', 'A first view of scope, team and budget range', 'Risks we would want to settle before a line of code is written']::text[], 'Apps Solutions Tech Team', 'Senior Solutions Architect', 'Book a Free Project Discovery Call', 'Thirty minutes with a senior solutions architect. Leave with a first view of scope, team and budget for your software project, and a written summary within two business days.'),
  ('ai-automation-assessment', 20, true, 'automation', 'AI and Automation Assessment', 45, 'Find the two or three workflows where AI pays for itself, and the ones where it will not.', 'Bring a process that eats your team''s hours: support tickets, data entry, document handling, lead follow-up. We map it with you and say which steps a chatbot or an automation can take over, what data it needs, and what the result is worth.', array['Walk through one or two of your manual workflows', 'Where a chatbot or an automation fits, and where it does not', 'Data, privacy and integration requirements', 'Expected savings and a sensible first pilot']::text[], 'Apps Solutions Tech Team', 'AI Solutions Lead', 'Book a Free AI and Automation Assessment', 'A 45 minute session with an AI solutions lead. We review your manual workflows and identify where chatbots and automation will save real hours, with a written summary afterwards.'),
  ('erp-and-systems-review', 30, true, 'erp', 'ERP and Systems Review', 45, 'For teams running on spreadsheets, disconnected tools or an ERP that no longer fits.', 'We look at how finance, inventory, sales and operations data moves through your business today. You get an honest opinion on whether to extend what you have, replace it, or build a system around the way you work.', array['Your current systems and where data is entered twice', 'Reporting gaps that slow down decisions', 'Build, buy or extend: the real cost of each option', 'A phased rollout that does not stop the business']::text[], 'Apps Solutions Tech Team', 'ERP Practice Lead', 'Book a Free ERP and Systems Review', 'A 45 minute review of your ERP, POS or management systems with a practice lead. Understand whether to extend, replace or build, and what a phased rollout would look like.'),
  ('technical-audit', 40, true, 'wrench', 'Technical Audit Session', 60, 'A second opinion on an existing product or codebase before you invest more in it.', 'For products that are slow, fragile or expensive to change. Share access or a walkthrough and a principal engineer will review architecture, code quality, performance and security with you, then rank what to fix first.', array['Architecture and code walkthrough', 'Performance, security and reliability concerns', 'What to fix now, what can wait and what to leave alone', 'Effort estimates for the top priorities']::text[], 'Apps Solutions Tech Team', 'Principal Engineer', 'Book a Free Technical Audit Session', 'Sixty minutes with a principal engineer reviewing your existing product or codebase. Get a ranked list of what to fix first, with effort estimates, at no cost.')
